// DM mission files: local cases S01–S10. Checks: [stat or 'a|b', band, when, pass, fail].
const PED = n => `systems/the-smoke/assets/tokens/people/ped-${String(n).padStart(2, '0')}.webp`;
export default {
  s01: {
    brief: `Jonah Mills's Highbury book club recorded last week's meeting. Clear as day on the tape, Derek (dead two years) makes a comment about the novel. The club is about to sell its archive to a collector, and nobody wants to vote with a ghost in the room. What's really going on: a living former member spliced in an old private joke of Derek's to scare the collector off. The collector has done nothing wrong and genuinely wants the archive. The twist: the "dead" joke is about a Dead Air pirate night in 1998, and Leon was there.`,
    openTitle: `Read aloud: a voice on the tape`,
    open: `Jonah Mills plays you the tape on a cassette player he has clearly had since 1985. Polite voices discussing a crime novel, a clink of teacups, and then a man's voice, warm and dry: "Well, I'd have shot the butler in chapter two and saved us all the trouble." Laughter on the tape. Jonah stops it. "That's Derek," he says. "Derek died two years ago." He looks at you over his glasses. "Before we sell the club archive, I'd like to know how."`,
    cast: ['jonah-mills', 'leon-marsh', 'ruth-bellamy', 'farah-yilmaz'],
    roles: {'jonah-mills': `Book club secretary. Mild, wry, quietly brave.`, 'leon-marsh': `Can hear a splice like other people hear a car alarm. Was at the 1998 pirate night.`, 'ruth-bellamy': `Keeps the club's old programmes in a cupboard at St Mary's New Church.`, 'farah-yilmaz': `Hall steward at the Rose and Crown, where the club meets. Runs it like a ship.`},
    scenes: [
      {at: 'HB2.4', title: `The Old Church, the vestry`, read: `The vestry at the Old Church on Church Street: a cupboard with a kettle, a sink and a tape player. Leon Marsh sits with headphones on, eyes closed, listening to Derek's line over and over. After the fifth time he opens his eyes. "It's a splice," he says. "Same phrase, same laugh, same room tone. It's from another tape." He takes the headphones off. "And I know that laugh. I was there."`,
        text: `Leon spots the repeated phrase; no roll needed for that. Finding the original takes digging.`,
        checks: [['grt', 'easy', `Sit with Leon through four hours of the club's old tapes to find the source`, `Tape 1998-03. "Shot the butler in chapter two." At a Dead Air pirate night.`, `You give up after two hours. Leon finds it the next day.`]]},
      {at: 'HB3.5', title: `St Mary's New Church, the record cupboard`, read: `Ruth Bellamy unlocks the record cupboard in the vestry at St Mary's New Church: boxes of parish magazines, choir lists and, on the bottom shelf, a box labelled BOOK CLUB 1990–2010. "I rent the space," she says. "What goes in it is between you and your conscience." In the box: old programmes for club socials.`,
        text: `The older event programme: same joke, same year, a club social at a Dead Air pirate night in 1998. A list of members who were there.`,
        checks: [['mus', 'easy', `Lift down the heavy boxes from the top shelf without bringing the shelf down`, `Down safely. The 1998 programme is in the second box.`, `A box splits. Choir lists everywhere.`],
          ['sav', 'medium', `Match the programme's member list to the current club`, `Only one current member was at the 1998 night: Margaret Pell.`, `Too many names.`]]},
      {at: 'HB6.3', title: `The Rose and Crown, the function room`, read: `The function room at the Rose and Crown on Albion Road, booked seven till ten. Farah Yilmaz stands at the door with her keys on a reel. Inside, twelve book-club members sit in a circle with teacups and copies of a novel. A collector in a tweed jacket sits among them, notebook open, delighted. One member, an elderly woman with a silk scarf, has gone very pale.`,
        text: `The surviving member, Margaret Pell, mid-meeting. The collector is about to make his offer. If someone recognises the joke, Margaret might own up.`,
        checks: [['frt', 'medium', `Ask Margaret, quietly, about the 1998 pirate night`, `She cries, a little. "Derek was my best friend. I didn't want strangers owning his voice."`, `She denies everything and leaves early.`],
          ['aim', 'easy', `When the collector reaches for his chequebook, flick the 1998 programme across the table so it lands in front of Margaret`, `It stops right in front of her. She looks at it and goes still.`, `It slides onto the floor.`]]}
    ],
    closeTitle: `Read aloud: Derek's joke`,
    close: `Margaret Pell holds the 1998 programme in both hands. "We used to go to the pirate nights," she says. "Derek and me. Dead Air, in a tower block, with a car battery." She smiles, wet-eyed. "He always said he'd shoot the butler in chapter two." She looks at the collector. "I didn't want you to have his voice. That's all." The collector, to everyone's surprise, closes his chequebook. "Then perhaps," he says gently, "it should stay with the club."`,
    notes: [`The decision: expose the edit, set up a sale where everyone knows the score, or talk the members into keeping a shared archive.`,
      `The old book-club tape is a physical prop.`,
      `Reward: £120 and 1 AD or BM Renown, once. After that the club books the crew a meeting room when they need one.`,
      `The collector is innocent. Don't make him a villain.`,
      `Leon being at the 1998 night is a nice link to AD. He knew Derek.`]
  },
  s02: {
    brief: `A gig organiser has lost the only master of an unreleased song, and someone keeps letting off a portable screamer alarm every time the band starts playing. A rival promoter is circling, offering to "save" the night. What's really going on: Miri Dane, the stage assistant, hid the master to make sure she gets the wages she's owed. The rival promoter is just using the chaos to poach the gig. The twist: the organiser owes Miri for three gigs, not one. He's been doing it to everybody.`,
    openTitle: `Read aloud: disaster`,
    open: `The organiser rings you, and behind him you can hear a band starting a song and then, immediately, an ear-splitting electronic shriek. The band stops. Someone swears. "Disaster," he says. "The only copy of the new song: gone. AND some joker keeps setting off a screaming alarm in rehearsals." The shriek goes off again. "Gig's tomorrow. Make both problems disappear." A pause. "Please."`,
    cast: ['rosa-baptiste', 'mags-cole', 'imogen-vale'],
    people: {'miri-dane': {name: 'Miri Dane', role: 'Stage assistant, owed three gigs\' wages', img: PED(5), look: 'Twenties, black hoodie, gaffer tape round her wrist, a personal alarm on her keyring.', manner: 'Quiet, stubborn, polite until pushed.', wants: 'Her wages. All of them.', line: 'I don\'t want to ruin anyone\'s gig. I want paying.'}},
    roles: {'rosa-baptiste': `At the chapel, because the gig is a benefit for the Mutual. Wants it to happen honestly.`, 'mags-cole': `Off-duty crew rep at the Shacklewell. Knows every crew member's grievances.`, 'imogen-vale': `Runs the record room at Abney Books. A note was left in a book she lent out.`, 'miri-dane': `The stage assistant who hid the master.`},
    scenes: [
      {at: 'SN1.3', title: `Abney Park Chapel, the rehearsal room`, read: `The rehearsal room at Abney Park Chapel: a draughty hall in the cemetery, the band's gear set up in a semicircle. The band starts to play. Three bars in, a shriek goes off from somewhere behind the stacked chairs. Everyone covers their ears. Rosa Baptiste, by the door, looks at you and raises an eyebrow.`,
        text: `Turn the room over. The alarm is a personal attack alarm wedged behind the chairs, triggered by a pull-cord tied to a mic stand. Someone who knows the band's setup did it.`,
        checks: [['mov', 'medium', `Climb over the stacked chairs to find the alarm before it goes off again`, `There: a personal alarm with a pull-cord tied to the mic stand.`, `It goes off in your face.`],
          ['sav', 'medium', `Work out who rigged it from how it was done`, `Gaffer tape in a crew's knot. Someone on the stage crew.`, `It's just tape.`]]},
      {at: 'SN5.5', title: `The Shacklewell Arms, the green room`, read: `The green room at the Shacklewell Arms. Mags Cole sits on the sofa with gaffer tape on her wrist like a bracelet. "Off duty means off duty," she says. "So why am I here?" You show her the knot on the alarm. She sighs. "That's a stage hand's knot. Miri's. She's owed money. A lot." She looks at you. "Don't make her the villain."`,
        text: `The visiting crew, and a lot of shrugging. Mags knows Miri is owed wages.`,
        checks: [['grt', 'easy', `Help Mags strip the stage after tonight's gig while she talks`, `By the end, she tells you where Miri hid the master: "in a library book".`, `You leave halfway. She stops talking.`]]},
      {at: 'SN2.3', title: `Abney Books, the side counter`, read: `Abney Books' side counter. Imogen Vale, chipped nail varnish, flicks through her lending book. "Miri borrowed a book on Tuesday," she says. "Brought it back yesterday." She pulls it from the shelf. Inside, tucked into the pages: a USB stick and a note. "THREE GIGS. £600. THEN YOU GET YOUR SONG."`,
        text: `The borrowed rehearsal book and note are a physical prop. Miri brings the master to the final soundcheck. The rival promoter offers a replacement act on the spot.`,
        checks: [['grf', 'medium', `Ease the USB stick out without tearing the old book's binding`, `Out clean. Imogen nods approvingly.`, `The binding cracks. Imogen glares.`],
          ['whl', 'medium', `Get to the soundcheck before the organiser takes the rival's replacement act`, `You arrive with the note as he picks up the phone.`, `He's already said yes to the rival.`],
          ['aim', 'easy', `Toss Miri the note from across the room at soundcheck so she knows you've read it`, `She catches it. She looks at you, and nods.`, `It flutters onto the drum kit.`]]}
    ],
    closeTitle: `Read aloud: three gigs`,
    close: `Miri Dane stands at the side of the stage with the USB stick in one hand and the organiser's wallet in the other, which he has just handed her, very reluctantly. "Three gigs," she says. "Six hundred." She counts it. Then she hands him the stick. "Your song." She turns to you. "I didn't want to ruin anyone's gig," she says. "I wanted paying." Behind her, the band starts to play. Nothing shrieks.`,
    notes: [`The decision: steal the master back, sort Miri's wages, sell the song, or put on an honest stand-in.`,
      `The borrowed rehearsal book and note is a physical prop.`,
      `Reward: £160 and 1 AD or VC Renown once. The Shacklewell offers the crew paid sound work later.`,
      `The organiser owing three gigs is the twist. Make him squirm.`]
  },
  s03: {
    brief: `A passenger "borrowed" a bag off a narrowboat on the Lea and vanished. Now two brothers are pointing at each other, swapping names like trading cards. What's really going on: the brothers swapped identities to dodge separate debts. The bag has a valuable saxophone in it belonging to a third musician. Nothing to do with the big conspiracy. The twist: the musician is the brothers' cousin. Christmas is going to be very awkward.`,
    openTitle: `Read aloud: my head hurts`,
    open: `The boat owner rings from a pub; you can hear a jukebox and someone laughing. "Got a narrowboat on the Lea. Passenger borrowed a bag and legged it." A long sip. "Now there's two brothers both saying the other one's got it." Another sip. "They keep giving each other's names. One's Darren, one's Dean, except Darren says he's Dean and Dean says he's Darren." A sigh. "My head hurts. Sort it?"`,
    cast: ['pearl-okonkwo', 'ezra-holt', 'basil-armitage'],
    people: {'brothers': {name: 'Darren and Dean Pryce', role: 'Brothers who swapped names', img: PED(15), look: 'Thirties, identical tracksuits, identical haircuts, one has a scar on his chin and won\'t say which one he is.', manner: 'Chaotic, charming, constantly contradicting each other.', wants: 'To dodge their debts and not get blamed by their cousin.', line: 'I\'m Dean. He\'s Darren. No, hang on.'}},
    roles: {'pearl-okonkwo': `At The Elderfield. The would-be buyer of the sax is one of her traders.`, 'ezra-holt': `Youth rowing volunteer who saw the passenger get off the boat.`, 'basil-armitage': `Cab dispatcher drinking at The Clapton Hart. Took one brother home last night.`, brothers: `Swapping names to dodge two separate debts.`},
    scenes: [
      {at: 'CL2.2', title: `The Princess of Wales`, read: `The saloon at The Princess of Wales, beside the Lea. The boat owner, a weathered man in a fleece, is three pints in. Through the window, his narrowboat bobs at the mooring. Ezra Holt, in a wet rowing hoodie, sits at the next table. "I saw him get off," Ezra says. "Bloke in a tracksuit with a big black case. Went towards Clapton."`,
        text: `The boat owner, three pints in. The bag had a saxophone case in it.`,
        checks: [['grt', 'easy', `Match the boat owner pint for pint until he remembers the passenger's face`, `"Scar on his chin. That's the one."`, `You're both too drunk to remember anything.`]]},
      {at: 'CL4.3', title: `The Clapton Hart, the back bar`, read: `The back bar at The Clapton Hart. Two men in identical tracksuits sit at opposite ends of a table, arguing. "I'm Dean," says one. "He's Darren." "No," says the other. "I'm Dean." Basil Armitage, in his cardigan at the bar, sips a half. "I took one of them home last night," he says. "Car twelve. The one with the scar. Dropped him at the Elderfield."`,
        text: `Two brothers, two stories. The one with the scar has the case.`,
        checks: [['frt', 'medium', `Get the brothers to admit which is which`, `"Fine. I'm Darren. He's Dean. We swapped because I owe Vic and he owes his ex."`, `They both insist they're Dean.`],
          ['mov', 'medium', `When the scarred one bolts for the door, catch him`, `You've got his collar at the door.`, `He's out and up the road.`]]},
      {at: 'CL6.3', title: `The attempted sale at The Elderfield`, read: `The function room at The Elderfield. A trader of Pearl's sits with a fat envelope. In front of him, on the table, an open saxophone case: a gold tenor sax, gleaming. Then the door opens and a young woman walks in with two people in recovery-crew jackets. "That's my sax," she says. "Darren. DEAN. Whichever one you are."`,
        text: `The musician turns up at the sale with a rival recovery crew. A chase can spill onto the Lea-side path.`,
        checks: [['whl', 'medium', `If the scarred brother runs with the case along the Lea, cut him off by road at the bridge`, `You're at the bridge first. He stops.`, `He's over the bridge and away.`],
          ['mus', 'medium', `Take the saxophone case off the brother before the recovery crew do`, `Case in your hands.`, `The recovery crew get there first.`],
          ['aim', 'easy', `Throw the case strap over the bollard so the boat can't pull away with it`, `Hooked. The case stays.`, `It splashes into the Lea. Everyone gasps.`]]}
    ],
    closeTitle: `Read aloud: Christmas`,
    close: `The musician holds her saxophone, checks every key, and then turns to the brothers, who are standing side by side looking at their trainers. "Darren," she says. "Dean." She looks from one to the other. "Cousins." She shakes her head. "Nan's going to hear about this." The brothers flinch at exactly the same moment. "At Christmas," she adds. "In front of everyone." Pearl, at the bar, laughs so loud the windows rattle.`,
    notes: [`The decision: recover the sax, buy it back for the musician, or negotiate a paid walk-away.`,
      `The musician's disputed instrument is a physical prop.`,
      `Reward: £160 and 1 TU or NM Renown once. The boat owner becomes a contact for the odd lift (not a free ride).`,
      `This is a comedy case. Play the brothers for laughs.`]
  },
  s04: {
    brief: `A charity sports day on the Marshes has lost its prize greyhound and its cash tin before the first whistle. The organiser wants it sorted before she ends up pointing at a volunteer in front of the whole crowd. What's really going on: the dog followed the smell of food into a delivery van. Ellis, a volunteer, took the tin to stop it being seized over a separate debt, then panicked. The twist: Ellis's "debt" is one of the forged entries from Vic's duplicate book. He never owed a penny.`,
    openTitle: `Read aloud: the greyhound`,
    open: `The organiser's voice is high and fast. "Sports fundraiser on the Marshes. We've lost the greyhound. Biscuit. She's the mascot." A pause. "AND the cash tin. Same morning." Another pause. "I don't want to accuse a volunteer in front of everyone. Find them first." A breath. "Please. Biscuit's very gentle. She likes sausages."`,
    cast: ['ollie-grant', 'gwen-hollis', 'marisol-vega'],
    people: {ellis: {name: 'Ellis Green', role: 'Volunteer who took the cash tin', img: PED(3), look: 'Twenties, fundraiser T-shirt, lanyard, eyes red from panicking.', manner: 'Kind, terrified, rehearsing excuses under his breath.', wants: 'To give the tin back without losing his volunteering place or his telly.', line: 'I wasn\'t stealing it! I was hiding it! From them!'}},
    roles: {'ollie-grant': `Groundsman at the North Pavilion. Saw the van.`, 'gwen-hollis': `Canal volunteer helping at the fundraiser. Knows Ellis.`, 'marisol-vega': `Running a delivery shift at New Spitalfields. The dog is in one of her vans.`, ellis: `Took the tin to hide it from a collector over a debt he doesn't owe.`},
    scenes: [
      {at: 'HM1.2', title: `The North Pavilion, the changing corridor`, read: `Hackney Marshes on a Saturday morning: bunting on the pavilion, a bouncy castle, two hundred people in fundraiser T-shirts. In the changing corridor, Ollie Grant leans on his strimmer. "Greyhound went that way," he says, pointing at the service court. "Following a van. Food delivery. Sausages for the barbecue." He shrugs. "Can't blame her."`,
        text: `Follow the dog's carrier: a food delivery van from New Spitalfields. The missing fundraiser greyhound on its lead is a physical prop.`,
        checks: [['whl', 'medium', `Follow the delivery van to New Spitalfields before it's unloaded`, `You pull in behind it at the market gate.`, `Lost it on the Lea Bridge Road roundabout.`],
          ['mov', 'easy', `Run across three football pitches to catch the van before it leaves the car park`, `You bang on the back doors. Too late, but you get the plate.`, `It's gone.`]]},
      {at: 'HM2.3', title: `New Spitalfields, the trader's unit`, read: `A trader's unit at New Spitalfields produce hall. Marisol Vega stands with her clipboard, looking at something on the floor. A greyhound, grey and gentle, is lying on a pile of sacks eating a friendly trader's sandwich. "Paperwork says forty kilos of sausages," Marisol says. "Doesn't say anything about a dog."`,
        text: `The dog, happily eating a sandwich. A sporting chase gets the dog back without anyone treating it like a weapon.`,
        checks: [['grt', 'easy', `Coax Biscuit out from under the pallets on your knees with a sausage`, `She comes, slowly, tail wagging.`, `She gets wedged further in.`],
          ['mus', 'easy', `Carry a forty-kilo box of sausages back to the van so the trader forgives the delay`, `He waves you off. "Take the dog."`, `You drop it. Sausages everywhere. Biscuit is delighted.`]]},
      {at: 'HM6.4', title: `The Leyton Jubilee Park pavilion, the office`, read: `The office at the Leyton Jubilee Park pavilion. Ellis Green, in a fundraiser T-shirt with a lanyard, sits on a chair with the cash tin on his knees, rehearsing. "I was going to give it back," he says. "I was! But a man came with a clipboard and said I owe Vic Randle four hundred quid and he'd take the tin." He looks up. "I don't owe anyone four hundred quid!"`,
        text: `Ellis, rehearsing an excuse. The missing fundraiser cash tin is a physical prop. A hired collector wants the tin and threatens Ellis's own stuff.`,
        checks: [['sav', 'medium', `Look at the collector's debt slip and spot the forgery`, `Uncrossed sevens. Vic's duplicate book (BB1). Ellis never owed a penny.`, `It looks real to you.`],
          ['btl', 'medium', `Stand between the collector and Ellis when he comes back`, `He looks at you, and at the slip, and leaves.`, `He takes Ellis's phone as "security".`]]}
    ],
    closeTitle: `Read aloud: Biscuit`,
    close: `At two o'clock, Biscuit the greyhound trots onto the Marshes on her lead with a sausage in her mouth, and two hundred people cheer. Ellis walks beside you with the cash tin, red-faced but smiling. The organiser hugs him, then hugs Biscuit, then, slightly awkwardly, hugs you. "I knew it wasn't him," she says. "I just didn't want to have to say so in front of everyone." Biscuit eats the organiser's sandwich.`,
    notes: [`The decision: return the dog and the cash, challenge the collector's claim, or let Ellis come clean and negotiate.`,
      `Two physical props: the greyhound on its lead and the cash tin.`,
      `Reward: £120 and 1 BM or BB Renown once. Both pavilions will book the crew for future events.`,
      `The dog is never a weapon or a hostage. Play her as a happy greyhound who likes sausages.`]
  },
  s05: {
    brief: `The Orient supporters' mascot costume has gone walkabout on match day, along with the ticket wallet. The supporters group wants both back before kick-off. What's really going on: a former volunteer borrowed the costume for a private gig. Their ex took the ticket wallet as leverage over a shared loan. Nothing to do with Meridian, just ordinary grief. The twist: the shared loan is from Vic's book. The ex is trying to pay it off before the collectors come.`,
    openTitle: `Read aloud: match day`,
    open: `Pauline Moss rings, and behind her you can hear a crowd singing on Brisbane Road. "It's match day and the mascot's gone." A pause. "Not the bloke. The COSTUME. Theo the Wyvern. Six-foot wings." Another pause. "And the ticket money. Two hundred tickets." The singing gets louder. "Get both back before kick-off or we're a laughing stock, love."`,
    cast: ['hassan-arif', 'liv-barrett', 'pauline-moss'],
    roles: {'hassan-arif': `At the Supporters Club. Former volunteer's friend, knows where the costume went.`, 'liv-barrett': `The ex, at The Coach and Horses. Took the ticket wallet as leverage.`, 'pauline-moss': `Runs the supporters. Loud, loyal, hates cheats.`},
    scenes: [
      {at: 'LY2.4', title: `The Supporters Club, the back room`, read: `The back room at the Leyton Orient Supporters Club, an hour before kick-off. Old shirts on the walls, a tea urn, a hook where a six-foot dragon costume should be hanging. Hassan Arif, in a polo shirt, is fiddling with his phone. "The costume?" he says, not looking up. "Volunteer borrowed it. Private gig. Kid's birthday at the Coach and Horses." He looks up. "She'll bring it back. After."`,
        text: `The volunteer looks shifty. The costume is at a private booking, and the ticket wallet is somewhere else entirely.`,
        checks: [['frt', 'medium', `Get Hassan to say where the ticket wallet went`, `"Her ex took it. Liv. Some loan they had together."`, `"I can get you that tomorrow."`]]},
      {at: 'LY6.3', title: `The Coach and Horses, the function room`, read: `The function room at The Coach and Horses on High Road Leyton: balloons, a bouncy castle, twenty seven-year-olds screaming, and in the middle of it, a six-foot dragon in an Orient shirt, dancing badly. It stops when it sees you. A muffled voice from inside the head says: "Oh no."`,
        text: `A private booking, and someone in a very sweaty costume. The missing team mascot costume is a physical prop. Liv Barrett, the ex, is at the bar with the ticket wallet.`,
        checks: [['grt', 'medium', `Do the rest of the party in the dragon costume so the volunteer can change and the kids aren't disappointed`, `Twenty minutes of conga. The kids cheer. You're drenched.`, `You last five minutes. A child cries.`],
          ['grf', 'medium', `Lift the ticket wallet from Liv's handbag at the bar`, `It's in your pocket.`, `She sees your hand.`]]},
      {at: 'LY1.2', title: `The stadium turnstiles`, read: `The concourse at Brisbane Road, ten minutes to kick-off. Crowds pouring through the turnstiles. Somewhere among them, a chancer with a bundle of tickets from the wallet, selling them cheap outside. The dragon costume, if you have it, needs to be on the pitch for the pre-match walkabout in eight minutes.`,
        text: `Beat the chancer with the tickets. The wallet and the costume are separate jobs.`,
        checks: [['mov', 'medium', `Get through the crowd to the chancer selling tickets`, `You grab his wrist. "These are the supporters' fund's."`, `He's gone into the crowd.`],
          ['whl', 'medium', `Drive the costume from the Coach and Horses to the stadium in eight minutes`, `The dragon walks out as the teams come on.`, `The teams are out. No dragon.`],
          ['aim', 'medium', `Throw the dragon head over the barrier to the volunteer on the pitch`, `Caught. The head goes on. The crowd roars.`, `It rolls onto the pitch. The ref is unimpressed.`]]}
    ],
    closeTitle: `Read aloud: Theo the Wyvern`,
    close: `Theo the Wyvern walks onto the pitch at Brisbane Road with his six-foot wings, waving at the crowd, smelling very strongly of a children's party. Pauline Moss stands by the tunnel with the ticket wallet, counting. "All there," she says. Then she sees Liv Barrett at the gate, looking lost, and her face softens. "Vic's book?" she says. Liv nods. Pauline sighs. "Come on, love. We'll sort it after the match. Orient till I die."`,
    notes: [`The decision: return the lot, keep the appearance fee, or negotiate a smaller deal.`,
      `The missing team mascot costume is a physical prop.`,
      `Reward: £120 and 1 BB or CH Renown once. A match steward might ask the crew back for paid match-day work.`,
      `Doing the conga in a dragon costume is the best possible use of a Grit roll.`]
  },
  s06: {
    brief: `A collector's missing cat has turned up in the background of a photo from an art sale. Clement Wren will pay for the cat's return, and he's very curious why the sale catalogue says two different things. What's really going on: a junior dealer has been selling copies as originals. The cat wandered into the packing room and a temp took it home without a clue. The temp hands it back happily when asked. The twist: Wren knew about the fakes. He wanted someone else to find them, so it couldn't be traced to him.`,
    openTitle: `Read aloud: the cat`,
    open: `Clement Wren's voice-note is accompanied by a photo: an art sale's packing room, crates and tissue paper, and in the corner, unmistakably, a fat ginger cat sitting on a crate marked FRAGILE. "Clement Wren," he says. "A collector of my acquaintance has lost her cat. Marmalade." A pause. "It has appeared in a photograph from an art sale. In the packing room." Another pause. "I will pay for the cat. And for an explanation of why the catalogue doesn't match itself."`,
    cast: ['clement-wren', 'saira-moon', 'beatrice-shaw'],
    roles: {'clement-wren': `Knew about the fakes. Wants someone else to find them.`, 'saira-moon': `The cat's owner. A residents' chair with photos of Marmalade on her phone. So many photos.`, 'beatrice-shaw': `The executor whose late brother's collection is being sold. Formal, grieving, furious about fakes.`},
    scenes: [
      {at: 'CG1.4', title: `Newington Green Meeting House, the library`, read: `The vestry library at Newington Green Meeting House. Saira Moon, in a smart coat over a hospital tunic, scrolls through her phone. "This is Marmalade at Christmas. This is Marmalade in a box. This is Marmalade judging me." She looks up. "She went missing on the 12th. The sale was on the 12th. The packing room is two streets away." She holds up the photo. "That's her. I'd know her anywhere."`,
        text: `The cat's owner, with photos. The packing room was at The Canonbury Tavern's function room, used as a sale venue. A temp worked there that day.`,
        checks: [['grt', 'easy', `Look at every single photo of Marmalade`, `Saira likes you. She gives you the temp's name from the sale's volunteer list.`, `You stop at photo forty. Saira sighs.`]]},
      {at: 'CG3.2', title: `The Canonbury Tavern, the saloon`, read: `The saloon at The Canonbury Tavern. Beatrice Shaw sits with her document case and two copies of the sale catalogue, one in each hand. "My late brother's collection," she says. "Catalogue one says 'original, signed'. Catalogue two, the one the buyers got, says the same. But the photos are different." She lays them side by side. "Different frames. Different signatures."`,
        text: `The private catalogue, side by side. The junior dealer has been selling copies as originals. The misattributed cat figurine is a physical prop: a ceramic cat in the sale, listed as "18th century" but stamped "Made in 2019".`,
        checks: [['sav', 'medium', `Compare the two catalogues and spot the switches`, `Six lots switched. Including a ceramic cat figurine: listed 1780, stamped 2019.`, `They look the same to you.`],
          ['grf', 'medium', `Turn the ceramic cat figurine over without anyone seeing and read the stamp`, `"Made in 2019." Oh dear.`, `It slips. You catch it. Everyone looks.`]]},
      {at: 'CG2.3', title: `The Estorick viewing`, read: `The viewing room at the Estorick Collection. A junior dealer, very young, very nervous, in a too-big suit, is showing a buyer a painting. He keeps glancing at the door. In his briefcase, visible as he opens it, is a fat envelope of cash: deposits. Through the window, a temp in a hoodie is walking past the courier court carrying a cat basket.`,
        text: `The dealer plans to leg it with the deposits after the viewing. The temp has the cat and will hand it back happily.`,
        checks: [['mov', 'medium', `Get out to the courier court and catch the temp with the cat basket`, `"Oh! Is she yours? She just followed me home." Marmalade is returned.`, `The temp's on the bus.`],
          ['mus', 'medium', `Block the door when the dealer tries to leave with the deposits`, `He stops. He sits down. He cries.`, `He pushes past.`],
          ['aim', 'easy', `Flick a catalogue across the floor so it lands at the dealer's feet, open at the cat`, `He looks down. He goes white.`, `It slides under a radiator.`]]}
    ],
    closeTitle: `Read aloud: Wren knew`,
    close: `Marmalade sits on Saira's lap, purring like a motorbike. Clement Wren watches from the doorway, in his linen suit. "Six fakes," you tell him. "And you knew." He smiles. "Did I?" He adjusts his pocket square. "Let's say I suspected. And I thought it would be better if someone else found out." He hands you an envelope. "For the cat," he says. "And for being the someone else."`,
    notes: [`The decision: get the cat home, stop the fraud, pinch the deposit, or negotiate restitution.`,
      `The misattributed cat figurine is a physical prop.`,
      `Reward: £160 and 1 GE or NM Renown once. A regular valuation slot is possible once the owner has been paid back.`,
      `The temp is innocent and very nice. Marmalade followed her home.`]
  },
  s07: {
    brief: `Tonight's double bill is missing a performer and a seriously expensive instrument. The promoter wants both back by soundcheck, and he's not admitting why the performer might have walked. What's really going on: the performer walked out over a fee cut nobody told them about. A completely separate chancer stole the instrument while the promoter was mid-row. Two problems, two fixes. The twist: the fee cut was Owen Pike's idea. The Velvet Circuit takes a skim off every show it "supports".`,
    openTitle: `Read aloud: soundcheck`,
    open: `The promoter rings, and you can hear a nervous sound engineer tapping a microphone: "One, two. One, two." The promoter's voice is strained. "Double bill tonight. Short one performer. And one VERY expensive instrument. A kora. Handmade. Mali." The mic taps again. "Find both by soundcheck or I'm finished."`,
    cast: ['jules-akin', 'dee-hassan', 'owen-pike'],
    people: {'awa-diallo': {name: 'Awa Diallo', role: 'Kora player, walked out over a fee cut', img: PED(7), look: 'Thirties, long braids, a bright wax-print coat, hands that move like music even when still.', manner: 'Proud, warm, absolutely immovable on fairness.', wants: 'Her full fee, and her grandfather\'s kora back.', line: 'My grandfather made that kora. You don\'t cut my fee and lose my kora on the same day.'}},
    roles: {'jules-akin': `Patch. At the Vortex, knows Awa from a Dead Air session.`, 'dee-hassan': `At Cafe OTO doing sound for the other half of the bill. Saw who walked out with the instrument case.`, 'owen-pike': `Off stage. The fee cut was his idea.`, 'awa-diallo': `The performer. Walked out over the fee cut.`},
    scenes: [
      {at: 'DA2.4', title: `Cafe OTO, the abandoned set`, read: `Cafe OTO's rehearsal room: a stage set for two performers. On one side, a stool with nothing on it and an empty kora stand. A setlist taped to the floor with "NOT PLAYING FOR £150" scrawled across it in marker. Dee Hassan, at the mix desk, looks up. "Performer walked out at four. Instrument walked out at half four. Different people."`,
        text: `The abandoned set. Two separate problems.`,
        checks: [['sav', 'medium', `Read the scene: the setlist, the empty stand, the scuff marks`, `Awa left angry, but carefully. The kora was taken in a hurry, by someone else, out the loading bay.`, `It all looks like one problem.`],
          ['grf', 'easy', `Check the loading bay door's lock for signs of tampering`, `Forced with a screwdriver. Not Awa.`, `It looks fine.`]]},
      {at: 'DA4.5', title: `The Vortex, the green room`, read: `The green room at the Vortex Jazz Club. A woman with long braids and a bright wax-print coat sits with a coffee, absolutely furious, very calmly. Patch from Dead Air sits beside her, nodding. "They told me £300," Awa Diallo says. "I arrive, they say £150. 'Support fee.'" She looks at you. "And now they've lost my grandfather's kora?"`,
        text: `The performer, still fuming. She'll identify the instrument, but might not play.`,
        checks: [['frt', 'medium', `Persuade Awa that the fee will be fixed and the kora found`, `"Full fee and my kora back, and I'll play."`, `"I'm not playing. Find my kora."`],
          ['grt', 'easy', `Sit and listen to Awa's whole story about the kora and her grandfather`, `By the end, she's laughing. She'll play.`, `You check your phone. She notices.`]]},
      {at: 'DA3.4', title: `Dalston Superstore, the back bar`, read: `The back bar at Dalston Superstore: pink neon, glitter. A man in a puffer jacket sits with a big, gourd-shaped instrument case on the seat beside him, talking to a buyer in a fake-fur coat. "Rare. African. Old," he's saying. "Two grand." The buyer is tapping her phone. The buyer leaves after the second meeting.`,
        text: `The would-be buyer and the thief. The missing performer instrument is a physical prop. A sub could save the night on a smaller fee.`,
        checks: [['mus', 'medium', `Take the kora case back from the thief before the buyer pays`, `Case in your arms. He doesn't argue.`, `He grips it. It's a tug of war.`],
          ['whl', 'medium', `If he bolts with the case, chase his car up Kingsland High Street`, `You box him in at the lights.`, `He's gone.`],
          ['aim', 'easy', `Knock the buyer's phone out of her hand with a thrown beer mat as she's about to transfer`, `It skitters across the bar. The deal is off.`, `It hits a barman.`]]}
    ],
    closeTitle: `Read aloud: grandfather's kora`,
    close: `Awa Diallo sits on the stool at Cafe OTO, the kora on her lap, tuning it string by string. The promoter stands beside the stage with an envelope: £300, the full fee. "It was Owen's idea," he mutters. "Support fee. He takes a cut of every show." Awa doesn't look up. "Then tell Owen," she says, "my grandfather made this kora." She plucks one string. The room goes silent. "And nobody takes a cut of that."`,
    notes: [`The decision: get the instrument back or buy it, and decide who plays.`,
      `The missing performer instrument is a physical prop.`,
      `Reward: £160 and 1 VC or AD Renown once. Future rehearsal access depends on the promoter actually paying his staff.`,
      `Owen's skim is a thread for VC3 and VC6.`]
  },
  s08: {
    brief: `Mo has found a strange key and a copied delivery note in the flat above Chicken Palace. Someone is selling the crew's room, and possibly their stuff, to a buyer while they're out on jobs. What's really going on: Kit Sorrell, a petty thief, is using an old tenancy mix-up to set up a burglary. Mo lost a real letter but hasn't sold anyone out. The twist: the old tenancy was Nia's. She lived in the crew's room before they did.`,
    openTitle: `Read aloud: Mo's key`,
    open: `Mo stands on the landing in his whites holding a key and a piece of paper. "Found a key in the flat," he says. "Not mine. Not yours." He holds up the paper: a delivery note, photocopied. "And this. A copied delivery note. With your room on it." He looks genuinely upset. "Someone's promised your room to a buyer while you're out." He puts his hand on his heart. "I swear it wasn't me, my friend."`,
    cast: ['mo-rahman', 'anya-byrne', 'ellis-morgan'],
    people: {'kit-sorrell': {name: 'Kit Sorrell', role: 'Petty thief working an old tenancy mix-up', img: PED(18), look: 'Twenties, baseball cap, too many keys on a carabiner, a removal trolley.', manner: 'Cocky, quick, folds the moment he\'s caught.', wants: 'An easy flat to empty and a buyer to flog it to.', line: 'It said "vacant" on the letter! Not my fault!'}},
    roles: {'mo-rahman': `Mo. Lost a real letter. Hasn't sold anyone out.`, 'anya-byrne': `Stage manager at Oslo who knows the false buyer.`, 'ellis-morgan': `Event organiser at the Castle Cinema where Kit has his second appointment.`, 'kit-sorrell': `The petty thief.`},
    scenes: [
      {at: 'FL3', title: `Chicken Palace and the stairwell`, read: `The flat above Chicken Palace. The smell of fried chicken through the floor. Your room is as you left it, mostly. But the door has been opened with a key, and someone has been through the drawers, carefully. On the stairwell, an old neighbour with a shopping trolley watches you. "Young lad with a cap," she says. "Twice this week. Had a key."`,
        text: `Work out what's missing. The neighbour on the stairs can recognise Kit even if the crew miss the letter. The Chicken Palace stolen keys are a physical prop.`,
        checks: [['sav', 'medium', `Work out what's missing and what Kit was looking for`, `Nothing taken. He was measuring up: what to take, how to carry it.`, `You can't tell if anything's gone.`],
          ['grf', 'medium', `Change the lock on your door before he comes back`, `New lock, new key. Mo approves.`, `The screws strip.`]]},
      {at: 'HC4.2', title: `Oslo Hackney, the bar`, read: `The bar at Oslo Hackney. Anya Byrne, the stage manager, points at a man in a suit at a table by the window. "That's your buyer," she says. "He's been telling everyone he's getting a 'furnished flat above a chicken shop' for a bargain." The man is reading a letter. On it: "VACANT — FL1 — FORMERLY N. BELL."`,
        text: `The "buyer", who thinks he's getting a bargain. The letter he has is old: a tenancy ending letter from Nia's time.`,
        checks: [['frt', 'medium', `Explain to the buyer that he's being conned`, `He goes pale. "But he showed me the key!"`, `He doesn't believe you.`],
          ['aim', 'easy', `Photograph the letter across the bar before he folds it away`, `Clear: "FL1 — Formerly N. Bell — tenancy ended March."`, `Blurred.`]]},
      {at: 'HC6.1', title: `The Castle Cinema, the foyer`, read: `The foyer at the Castle Cinema. Ellis Morgan, with her phones on loud, points across the foyer at a young man in a baseball cap with too many keys on a carabiner and a removal trolley folded under his arm. "Second appointment," she says. "He's meeting another buyer here." Kit Sorrell sees you and his face drops.`,
        text: `Kit's second appointment. After two enquiries Kit turns up at the flat with a removal trolley. Defend the room, follow the trolley, or have a word with the buyer.`,
        checks: [['mov', 'medium', `Catch Kit before he's out the door`, `You've got his collar. He folds immediately.`, `He's out and running.`],
          ['whl', 'medium', `If he runs, beat him back to the flat`, `You're on the landing when he arrives with the trolley.`, `He's already in.`],
          ['mus', 'easy', `Take his removal trolley off him so he can't empty anything`, `Trolley's yours now.`, `He hangs on.`]]}
    ],
    closeTitle: `Read aloud: formerly N. Bell`,
    close: `Mo reads the old letter in the kitchen at Chicken Palace, his reading glasses on. "Nia," he says. "She lived up there. Two years. Before you." He folds the letter. "Lovely girl. Always paid on Friday. Always said hello." He looks at you. "When she left, she left in a hurry. Didn't take everything." He nods at the ceiling. "There's a box in the loft. I never threw it away." He looks at you over his glasses. "You want to see?"`,
    notes: [`The decision: catch Kit, arrange a supervised return, or sell the buyer the crew's junk.`,
      `The Chicken Palace stolen keys are a physical prop.`,
      `Reward: £80 or a bit off the rent, and 1 CH or LD Renown once. Mo becomes a better early warning.`,
      `Nia's box in the loft is a hook for RT. What's in it is the GM's call (old tapes, a notebook, a photo).`]
  },
  s09: {
    brief: `Two ex-business partners have each hired the crew to get the same film projector back before a community screening. Neither knows the other has hired them. A third person has already rented it out to someone else. What's really going on: one partner bought it; the other paid for the repair that made it work. A visiting promoter hired it out without asking either. The twist: the visiting promoter is the projector's original maker. He thinks it's still his.`,
    openTitle: `Read aloud: same projector`,
    open: `Two calls, ten minutes apart. Partner one, Tom Sethi: "Get my projector back. Please. It's a 1970s Elmo. It's beautiful." Partner two, Vee Calder: "Get MY projector back. I fixed it. Six months of my life." You put the phone down. You check. Same projector. You ring the screening venue. "Oh, that one?" they say. "Someone else hired it out to us last week." Lovely.`,
    cast: ['tom-sethi', 'martin-rusk', 'vee-calder'],
    people: {'otto-brandt': {name: 'Otto Brandt', role: 'Visiting promoter and the projector\'s original maker', img: PED(20), look: 'Seventies, a German engineer\'s cardigan, a screwdriver in his breast pocket, a suitcase of spare lenses.', manner: 'Courteous, stubborn, fiercely proud of his work.', wants: 'His machine shown properly, and credited.', line: 'I built this machine in 1974. I think I may hire it out, ja?'}},
    roles: {'tom-sethi': `Bought the projector. Easy-going, guilty-looking even when innocent.`, 'martin-rusk': `At The Kenton, oddly. Hiring the community screening venue's back room for a private meeting. Watches everything.`, 'vee-calder': `Fixed the projector. Will film anything if asked nicely.`, 'otto-brandt': `Hired it out. Built it in 1974.`},
    scenes: [
      {at: 'WW2.3', title: `The HBC Community Centre, the office`, read: `The office at the HBC Community Centre. Tom Sethi and Vee Calder have both turned up, separately, and are now sitting on opposite sides of the room with receipts in their hands, not looking at each other. Tom's receipt: "Elmo 16mm projector, £400." Vee's receipt: "Parts and labour, Elmo 16mm, £380." They both look at you. "Well?" they say, at the same time.`,
        text: `Both receipts. One bought it; one made it work. Neither knows about the third hire.`,
        checks: [['sav', 'medium', `Work out who has the stronger claim, fairly`, `Tom owns it. Vee has a lien for her repair. Neither can sell it without the other.`, `You can't decide.`],
          ['grt', 'easy', `Sit through an hour of them arguing about who did more for the projector`, `By the end, they're nearly laughing.`, `You leave before they calm down.`]]},
      {at: 'WW5.2', title: `The Kenton, the saloon`, read: `The saloon at The Kenton on Kenton Road. A man in his seventies in a German engineer's cardigan sits with a suitcase of spare lenses and a half of bitter. "The Elmo?" Otto Brandt says. "Ja. I hired it to the screening." He smiles. "I built it. 1974. Serial number 0001." He taps the table. "I think I may hire it out." In the corner, Martin Rusk drinks a coffee and says nothing at all.`,
        text: `The visiting hirer, all innocent eyes. Otto built it and thinks it's still his. Rusk is here for an unrelated meeting, and notices the crew.`,
        checks: [['frt', 'medium', `Explain to Otto, gently, that he sold it fifty years ago`, `He laughs. "Ja, ja. But I still love it."`, `He's offended. "I am the maker!"`]]},
      {at: 'WW6.5', title: `Hub67, the projection room`, read: `The projection room at Hub67, an hour before the community screening. The Elmo sits on its stand, beautiful, chrome and black. Forty people are already in the hall, waiting for a film. An equipment van pulls up outside, sent by someone to collect it.`,
        text: `Grab the projector. The equipment van arrives after the second meeting. The screening can go ahead with a replacement if nobody agrees. The disputed hired projector is a physical prop.`,
        checks: [['mus', 'medium', `Lift the heavy projector off its stand before the van crew get in`, `It's in your arms. Heavy, but yours.`, `The van crew are in the room.`],
          ['whl', 'medium', `Park across the van's path so it can't get to the door`, `Blocked. The van crew argue with each other.`, `They get round you.`],
          ['grf', 'medium', `Thread the film and get the screening started with the Elmo, whoever owns it`, `The film flickers into life. Forty people cheer. Otto cries.`, `It jams. The audience groans.`]]}
    ],
    closeTitle: `Read aloud: serial number 0001`,
    close: `The Elmo projects a black-and-white film onto Hub67's wall, clicking softly. Tom, Vee and Otto sit in the back row together, watching. Nobody planned it. "I built her," Otto whispers. "I bought her," Tom whispers. "I fixed her," Vee whispers. They look at each other. Then, for the first time, they all laugh. On the screen, a train pulls into a station. Forty people cheer.`,
    notes: [`The decision: get it back for one of them, split the hire money, or buy one partner out. Only one client can pay; no double fees for promising both the same thing.`,
      `The disputed hired projector is a physical prop.`,
      `Reward: £160 from one client who knows the score, and 1 BM or GE Renown once.`,
      `Rusk at The Kenton is a cameo. Let him watch. He remembers faces.`]
  },
  s10: {
    brief: `An amateur runner's sponsor has vanished with her showcase deposit. Femi has heard the same "sponsor" made the exact same promise to two other athletes. The sports venues are completely innocent; it's just one con man in a nice suit. What's really going on: Callum Redd, a fake agent, invented an endorsement deal and sold the same place to three athletes. The twist: Callum Redd's real name is on Vic's duplicate book. He owes Vic more than he's stolen.`,
    openTitle: `Read aloud: my money`,
    open: `The runner rings, out of breath, from a running track. "My sponsor's done a runner. With my deposit." She laughs, bitterly, at her own joke. "Three hundred quid. For a 'showcase'." A pause. "And Femi says the same 'sponsor' has promised the same deal to two other girls." Another pause. "I just want my money." A longer pause. "And maybe to see his face when he's caught."`,
    cast: ['celia-voss', 'ewan-cole', 'helen-drew'],
    people: {'callum-redd': {name: 'Callum Redd', role: 'Fake sports agent', img: PED(19), look: 'Thirties, a suit that\'s nicer than his shoes, a lanyard he printed himself, a smile that sells.', manner: 'Smooth until cornered, then a sprinter.', wants: 'Three deposits and a head start.', line: 'Exclusive, babe. You\'re the only one I\'m doing this for.'}, femi: {name: 'Femi', role: 'Amateur runner who spotted the con', img: PED(2), look: 'Nineteen, club vest, spikes over one shoulder, a phone full of screenshots.', manner: 'Sharp, funny, furious on her friends\' behalf.', wants: 'Her friends\' money back and Redd\'s face in the club newsletter.', line: 'Three of us. Same email. Same "exclusive". He didn\'t even change the font.'}},
    roles: {'celia-voss': `At the Timber Lodge for a sponsorship lunch. Nothing to do with Redd, but he's name-dropping Meridian.`, 'ewan-cole': `Garage owner at The Leyton Star. Redd owes him for a car.`, 'helen-drew': `Event administrator at the Hockey and Tennis Centre. Clause four, sub-section two.`, 'callum-redd': `The con man.`, femi: `Spotted the con.`},
    scenes: [
      {at: 'ON2.4', title: `The Lee Valley Hockey and Tennis Centre, café`, read: `The café at the Lee Valley Hockey and Tennis Centre. The runner sits with Femi, a nineteen-year-old in a club vest with her spikes over one shoulder, who is scrolling through screenshots. "Three of us," Femi says. "Same email. Same 'exclusive'." She turns the phone round. "He didn't even change the font." Helen Drew, at the next table with a lanyard and a laptop, looks up. "That company isn't registered with us," she says. "At all."`,
        text: `The runner and Femi. Helen Drew confirms the "sponsor" isn't real.`,
        checks: [['grt', 'easy', `Do a training lap with the runner while she tells you everything`, `By the end of 400 metres, you know Redd's next meeting.`, `You're out of breath at 200. She laughs.`]]},
      {at: 'ON3.3', title: `The Timber Lodge, the side booth`, read: `The Timber Lodge café in the Olympic Park. In a side booth, a man in a suit nicer than his shoes, with a printed lanyard, is pitching to a fourth athlete. "Exclusive, babe," he's saying. "You're the only one I'm doing this for." At the next table, Celia Voss, at a sponsorship lunch, raises an eyebrow. Redd has just said "Meridian are one of my partners."`,
        text: `Redd's next meeting, from his diary. He scarpers as soon as an athlete questions the paperwork.`,
        checks: [['aim', 'medium', `Photograph Redd's "contract" across the café as he slides it to the athlete`, `Clear: a fake company name and a bank account.`, `Blurred.`],
          ['frt', 'medium', `Ask Celia, at the next table, whether Meridian work with Callum Redd`, `"Never heard of him, darling." She says it loudly. Redd hears.`, `She ignores you.`]]},
      {at: 'ON6.3', title: `The Leyton Star, the function room`, read: `The function room at The Leyton Star. All three athletes, Femi, and Ewan Cole in garage overalls. "Callum Redd," Ewan says. "Owes me eight hundred quid for a Golf." Then the door opens and Redd walks in for his third appointment. He sees the room. He sees all three athletes. He sees Ewan. He turns and runs.`,
        text: `All the rival offers in one room. A sporting chase can grab the deposit bag.`,
        checks: [['mov', 'hard', `Chase Redd down High Road Leyton (with three athletes beside you)`, `Femi tackles him at the bus stop. You get there a second later.`, `He's faster than you. Femi isn't. She catches him anyway.`],
          ['mus', 'medium', `Hold Redd down until he hands over the deposit bag`, `He hands it over, sulking.`, `He wriggles free.`],
          ['whl', 'medium', `If he gets to his car, block it in at the junction`, `Boxed in. He gives up.`, `He's gone.`]]}
    ],
    closeTitle: `Read aloud: his face`,
    close: `Callum Redd sits on the bench at the bus stop on High Road Leyton, his nice suit torn at the knee, while three runners and Femi stand round him. Femi takes a photo of his face on her phone. "For the club newsletter," she says. Ewan Cole leans in. "And the Golf," he says. Redd looks up at you. "There's a bloke called Vic," he says, miserably, "who's going to be very interested in where I am." Femi takes another photo.`,
    notes: [`The decision: recover the money, expose the fake deal, or set up a genuine small club partnership.`,
      `Reward: £160 and 1 CH or BB Renown once. Femi gets a real sponsor lead, not instant fame.`,
      `Redd's real name in Vic's book is a hook for BB.`,
      `Femi tackling him is the best possible ending.`]
  }
};
